ALTER TABLE "league"."draft_picks" ADD COLUMN "development_facts" jsonb;
--> statement-breakpoint
-- One-time facts for drafts already in the archive. Future imports populate this column automatically.
UPDATE "league"."draft_picks" AS pick
SET "development_facts" = seed.facts
FROM jsonb_to_recordset($draft_facts$
