$draft_facts$::jsonb) AS seed(year integer, "playerId" text, facts jsonb)
WHERE pick.season_year = seed.year
  AND pick.player_id = seed."playerId"
  AND pick.drafted_on = (seed.facts->>'draftedOn')::date
  AND pick.development_facts IS NULL;
